/// <summary>
/// This is an extension class for the TAMRebateTable table.
/// </summary>
[ExtensionOf(tableStr(TAMRebateTable))]
final class TAMRebateTable_Metcash_Extension
{
}

Method.Source:
/// <summary>
/// Validate the rebate lines for a rebate deal.
/// </summary>
/// <returns>boolean</returns>
public boolean validateRebateTable()
{
    boolean ret;
    TAMRebateDeal rebateDeal;

    select firstonly METVolumetricTierDeal, RecId from rebateDeal
        where rebateDeal.RecId == this.RebateDeal;

    if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        TAMRebateTable rebateTableLoc;

        select count(RecId) from rebateTableLoc
            where rebateTableLoc.RebateDeal == this.RebateDeal;

        if (rebateTableLoc.RecId > 2)
        {
            throw error("@MET:METVolumetricValidation");
        }

        select firstonly METTierLineType, RecId from rebateTableLoc
            where rebateTableLoc.RebateDeal == this.RebateDeal
            && rebateTableLoc.RecId != this.RecId;

        if (rebateTableLoc.RecId && this.RecId != rebateTableLoc.RecId && rebateTableLoc.METTierLineType == this.METTierLineType)
        {
            throw error("@MET:NoSimilarLineType");
        }

        TAMRebateTable tamRebateTable;

        select firstonly tamRebateTable
            where tamRebateTable.RebateId != this.RebateId
            && tamRebateTable.RebateDeal == rebateDeal.RecId;

        if (tamRebateTable.RecId && tamRebateTable.pricingAttributeDetailsHeader() != this.pricingAttributeDetailsHeader())
        {
            warning(strFmt("@MET:NoMatchingPriceAttributes"));
        }

    }
    return ret;
}

/// <summary>
/// Before update the record validates the rebates should not have same line types and more than two records.
/// </summary>
public void update()
{
    TAMRebateDeal rebateDeal;

    select firstonly METVolumetricTierDeal from rebateDeal
        where rebateDeal.RecId == this.RebateDeal;

    if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        this.validateRebateTable();
    }

    next update();
}
